import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Bell, ChevronRight, Home, Camera, User, AlertTriangle } from "lucide-react";

export default function HomePage() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState("home");

  const recentDetections = [
    {
      id: 1,
      disease: "Sigatoka Negra",
      plant: "Banano",
      time: "2h ago",
      risk: "high",
    },
    {
      id: 2,
      disease: "Mancha Foliar",
      plant: "Banano",
      time: "Jul 2, 2024",
      risk: "medium",
    },
    {
      id: 3,
      disease: "Hoja Sana",
      plant: "Banano",
      time: "Jun 15, 2024",
      risk: "low",
    },
  ];

  const riskColor = (risk) => {
    if (risk === "high") return "bg-red-100 text-red-600";
    if (risk === "medium") return "bg-yellow-100 text-yellow-600";
    return "bg-green-100 text-green-600";
  };

  const riskLabel = (risk) => {
    if (risk === "high") return "Alto";
    if (risk === "medium") return "Medio";
    return "Sano";
  };

  return (
    <div className="min-h-screen bg-[#f5f2ec] flex flex-col max-w-md mx-auto relative">

      {/* Header */}
      <div className="px-5 pt-12 pb-4">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-full bg-[#d8e4d0] flex items-center justify-center overflow-hidden">
              <User size={20} className="text-[#6b8f5e]" />
            </div>
            <div>
              <p className="text-xs text-[#7a8c7b]">Hello,</p>
              <p className="text-sm font-medium text-[#2c3e2d]">Welcome Back 👋</p>
            </div>
          </div>
          <button className="w-10 h-10 rounded-full bg-white border border-[#c8d4c2] flex items-center justify-center">
            <Bell size={18} className="text-[#6b8f5e]" />
          </button>
        </div>

        {/* Banner */}
        <div className="relative rounded-2xl overflow-hidden bg-[#4a6741] h-40 flex items-end p-4">
          {/* Fondo decorativo */}
          <div className="absolute inset-0 opacity-20">
            <div className="absolute top-0 right-0 w-32 h-32 rounded-full bg-[#8aad7a] -translate-y-8 translate-x-8" />
            <div className="absolute bottom-0 left-0 w-24 h-24 rounded-full bg-[#6b8f5e] translate-y-8 -translate-x-4" />
          </div>
          <div className="relative z-10">
            <p className="text-white font-medium text-base leading-tight">
              Protege tus cultivos,
            </p>
            <p className="text-white font-medium text-base leading-tight mb-1">
              asegura tu futuro
            </p>
            <p className="text-[#c8dfc0] text-xs">
              Detecta enfermedades de Sigatoka
            </p>
          </div>
        </div>
      </div>

      {/* Scan Plant */}
      <div className="px-5 mb-4">
        <button
          onClick={() => navigate("/scan")}
          className="w-full bg-white border border-[#c8d4c2] rounded-2xl p-4
                     flex items-center justify-between hover:bg-[#f0ede6] transition-colors"
        >
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-[#e8f0e4] flex items-center justify-center">
              <LeafIcon />
            </div>
            <div className="text-left">
              <p className="text-sm font-medium text-[#2c3e2d]">Scan Plant</p>
              <p className="text-xs text-[#7a8c7b]">
                Toma una foto para detectar enfermedades
              </p>
            </div>
          </div>
          <ChevronRight size={18} className="text-[#7a8c7b]" />
        </button>
      </div>

      {/* Detecciones recientes */}
      <div className="px-5 flex-1">
        <div className="flex items-center justify-between mb-3">
          <p className="text-sm font-medium text-[#2c3e2d]">
            Recent Detections
          </p>
          <button
            onClick={() => navigate("/history")}
            className="text-xs text-[#6b8f5e] hover:underline"
          >
            See All
          </button>
        </div>

        <div className="space-y-3">
          {recentDetections.map((item) => (
            <button
              key={item.id}
              onClick={() => navigate(`/result/${item.id}`)}
              className="w-full bg-white border border-[#c8d4c2] rounded-2xl p-3
                         flex items-center justify-between hover:bg-[#f0ede6] transition-colors"
            >
              <div className="flex items-center gap-3">
                <div className="w-9 h-9 rounded-xl bg-[#e8f0e4] flex items-center justify-center">
                  <SmallLeafIcon />
                </div>
                <div className="text-left">
                  <p className="text-sm font-medium text-[#2c3e2d]">
                    {item.disease}
                  </p>
                  <p className="text-xs text-[#7a8c7b]">{item.plant}</p>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <span
                  className={`text-xs px-2 py-0.5 rounded-full font-medium ${riskColor(item.risk)}`}
                >
                  {riskLabel(item.risk)}
                </span>
                <p className="text-xs text-[#7a8c7b]">{item.time}</p>
              </div>
            </button>
          ))}
        </div>
      </div>

      {/* Alerta informativa */}
      <div className="px-5 mt-4">
        <div className="bg-[#fff8e6] border border-[#f0d080] rounded-2xl p-3 flex items-start gap-2">
          <AlertTriangle size={16} className="text-[#c89a00] mt-0.5 shrink-0" />
          <p className="text-xs text-[#7a6500]">
            La detección temprana puede salvar tus cultivos. Escanea tus plantas regularmente.
          </p>
        </div>
      </div>

      {/* Bottom Navigation */}
      <div className="sticky bottom-0 bg-white border-t border-[#c8d4c2] px-6 py-3 mt-4">
        <div className="flex items-center justify-around">

          <button
            onClick={() => setActiveTab("home")}
            className={`flex flex-col items-center gap-1 px-4 py-1.5 rounded-xl transition-colors
              ${activeTab === "home"
                ? "bg-[#6b8f5e] text-white"
                : "text-[#7a8c7b]"
              }`}
          >
            <Home size={20} />
            <span className="text-xs">Home</span>
          </button>

          <button
            onClick={() => {
              setActiveTab("scan");
              navigate("/scan");
            }}
            className={`flex flex-col items-center gap-1 px-4 py-1.5 rounded-xl transition-colors
              ${activeTab === "scan"
                ? "bg-[#6b8f5e] text-white"
                : "text-[#7a8c7b]"
              }`}
          >
            <Camera size={20} />
            <span className="text-xs">Scan</span>
          </button>

          <button
            onClick={() => {
              setActiveTab("profile");
              navigate("/profile");
            }}
            className={`flex flex-col items-center gap-1 px-4 py-1.5 rounded-xl transition-colors
              ${activeTab === "profile"
                ? "bg-[#6b8f5e] text-white"
                : "text-[#7a8c7b]"
              }`}
          >
            <User size={20} />
            <span className="text-xs">Profile</span>
          </button>

        </div>
      </div>

    </div>
  );
}

function LeafIcon() {
  return (
    <svg width="22" height="22" viewBox="0 0 80 80" fill="none">
      <ellipse cx="40" cy="35" rx="18" ry="26" fill="#8aad7a" opacity="0.85" transform="rotate(-8 40 35)" />
      <ellipse cx="42" cy="33" rx="14" ry="22" fill="#6b8f5e" opacity="0.7" transform="rotate(6 42 33)" />
      <line x1="40" y1="60" x2="40" y2="72" stroke="#6b8f5e" strokeWidth="2" strokeLinecap="round" />
    </svg>
  );
}

function SmallLeafIcon() {
  return (
    <svg width="18" height="18" viewBox="0 0 80 80" fill="none">
      <ellipse cx="40" cy="35" rx="18" ry="26" fill="#8aad7a" opacity="0.85" transform="rotate(-8 40 35)" />
      <ellipse cx="42" cy="33" rx="14" ry="22" fill="#6b8f5e" opacity="0.7" transform="rotate(6 42 33)" />
      <line x1="40" y1="60" x2="40" y2="72" stroke="#6b8f5e" strokeWidth="2" strokeLinecap="round" />
    </svg>
  );
}
